/**
 * Inserts markup that has already been sanitized or generated by a trusted
 * local renderer without assigning to innerHTML.
 */
export function replaceWithTrustedHtml(element: Element, html: string): void {
  const Parser = element.ownerDocument.defaultView?.DOMParser;
  if (!Parser) throw new Error('This document cannot parse HTML fragments.');
  const parsed = new Parser().parseFromString(html, 'text/html');
  const nodes = Array.from(parsed.body.childNodes, node => element.ownerDocument.importNode(node, true));
  element.replaceChildren(...nodes);
}
